{
  "segment_function": "Discusses the distinction between social and political animal classifications, analyzing how Aristotle's zōon politikon became translated as animal socialis and contrasting the private household with the public political realm of the polis.",
  "claims": [
    {
      "claim": "Action is the exclusive prerogative of man and is entirely dependent upon the constant presence of others, whereas labor and fabrication do not strictly require human company in the same manner.",
      "claim_type": "author_position",
      "supporting_excerpt": "Action alone is the exclusive prerogative of man; neither a beast nor a god is capable of it, and only action is entirely dependent upon the constant presence of others.",
      "support_kind": "direct",
      "qualifications": [
        "Labor does not need the presence of others",
        "A fabricator working alone would lose specifically human quality or resemble a divine demiurge"
      ],
      "confidence": 1.0
    },
    {
      "claim": "The translation of Aristotle's zōon politikon as animal socialis and homo est naturaliter politicus, id est, socialis reflects a loss of the original Greek understanding of politics.",
      "claim_type": "author_position",
      "supporting_excerpt": "More than any elaborate theory, this unconscious substitution of the social for the political betrays the extent to which the original Greek understanding of politics had been lost.",
      "support_kind": "direct",
      "qualifications": [
        "The word 'social' is Roman in origin and lacks an equivalent in Greek language or thought"
      ],
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "vita activa",
      "definition": "Human life in so far as it is actively engaged in doing something, always rooted in a world of men and man-made things."
    },
    {
      "term": "bios politikos",
      "definition": "A second life received alongside private life upon the rise of the city-state, constituted by action (praxis) and speech (lexis)."
    }
  ],
  "distinctions": [
    {
      "item_a": "Political association (polis)",
      "item_b": "Natural association centered on the home and family (oikia)",
      "distinction": "According to Greek thought, the human capacity for political organization stands in direct opposition to the natural association of the home whose center is the family."
    },
    {
      "item_a": "What is one's own (idion)",
      "item_b": "What is communal (koinon)",
      "distinction": "A citizen belongs to two orders of existence, creating a sharp distinction between private personal life and communal existence."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Distinction between zōon politikon and animal socialis",
    "Exclusion of the merely necessary or useful from the bios politikos",
    "The relationship between action, speech, and the presence of others"
  ]
}

